from common import *
H=[('Licitante Cobalto-12','R$ 12.400,00','14:28:51'),('Licitante Âmbar-47','R$ 11.900,00','14:20:03'),('Licitante Âmbar-47','R$ 11.000,00','13:55:40'),('Licitante Jade-08','R$ 10.500,00','13:41:12'),('Licitante Cobalto-12','R$ 10.000,00','12:02:09')]
def hist(rows=H,n=5,compact=False):
    tr=''.join(f'<tr><td class="num muted">#{len(rows)-i:02d}</td><td>{a}{" <span class=\"badge b-closed\" style=\"font-size:10px;padding:1px 6px\">você</span>" if "Âmbar" in a else ""}</td><td class="num" style="text-align:right;font-weight:600">{v}</td><td class="num muted" style="text-align:right">{t}</td></tr>' for i,(a,v,t) in enumerate(rows[:n]))
    return f'<table><tr><th>Seq.</th><th>Licitante (alias)</th><th style="text-align:right">Lance</th><th style="text-align:right">Hora</th></tr>{tr}</table>'
def panel(status,timer,price_lbl,price,minimo,pos,action,extra='',fs=30):
    return f'''<div class="col" style="gap:16px">{status}
<div class="card" style="padding:18px"><div class="row" style="justify-content:space-between;align-items:flex-start;flex-wrap:wrap"><div><div class="small muted">{price_lbl}</div><div class="price" style="font-size:{fs}px;line-height:1.1;white-space:nowrap">{price}</div><div class="small muted" style="margin-top:4px">{minimo}</div></div>{timer}</div>{pos}</div>
{action}{extra}</div>'''
def timer(v='02:14:09',sub='até 23/10 · 17:00 BRT',lbl='Termina em',warn=False):
    st='background:var(--warn-soft);border-color:#E9CF9C;' if warn else ''
    return f'<div class="card" style="padding:10px 14px;text-align:right;box-shadow:none;{st}"><div class="xs muted">{lbl}</div><div class="num" style="font-size:26px;font-weight:600">{v}</div><div class="xs muted">{sub}</div></div>'
def form(val='12.900,00',err=None,btn='Dar lance de R$ 12.900,00',dis=False,note='Disponível <b class="num">R$ 19.900,00</b> + seu compromisso atual neste lote'):
    e=f'<div class="help e">{ic("circle-alert",14)}<span>{err}</span></div>' if err else '<div class="help">Mínimo R$ 12.900,00 · incremento mínimo R$ 500,00</div>'
    chips=''.join(f'<span class="btn o sm num">{x}</span>' for x in ['R$ 12.900','R$ 13.400','R$ 13.900'])
    return f'''<div class="card" style="padding:18px"><span class="lbl">Seu lance (R$)</span><div class="input {"err" if err else ""}" style="height:48px"><span class="muted">R$</span><span class="num" style="font-size:17px;font-weight:600">{val}</span></div>{e}<div class="row" style="margin-top:10px;gap:8px">{chips}</div><span class="btn p lg {"dis" if dis else ""}" style="width:100%;margin-top:14px">{ic('gavel',18)}{btn}</span><div class="small muted" style="margin-top:10px;display:flex;gap:6px">{ic('wallet',15)}<span>{note}</span></div></div>'''
